/**
 * // This is the interface that allows for creating nested lists.
 * class NestedInteger {
 *   public:
 *     NestedInteger();
 *     NestedInteger(int value);
 *     bool isInteger() const;
 *     void add(const NestedInteger &ni);
 *     void setInteger(int value);
 * };
 */
class Solution {
public:
    int i = 0;
    NestedInteger parse(const string& s) {
        if (s[i] == '[') {
            i++;
            NestedInteger ni;
            while (s[i] != ']') {
                ni.add(parse(s));
                if (s[i] == ',') i++;
            }
            i++;
            return ni;
        }
        int sign = 1;
        if (s[i] == '-') { sign = -1; i++; }
        int val = 0;
        while (i < (int)s.size() && isdigit(s[i])) val = val * 10 + (s[i++] - '0');
        return NestedInteger(sign * val);
    }
    NestedInteger deserialize(string s) {
        return parse(s);
    }
};

