var deserialize = function(s) {
    let i = 0;
    function parse() {
        if (s[i] === '[') {
            i++;
            const ni = new NestedInteger();
            while (s[i] !== ']') {
                ni.add(parse());
                if (s[i] === ',') i++;
            }
            i++;
            return ni;
        }
        let j = i;
        while (j < s.length && (/[0-9]/.test(s[j]) || s[j] === '-')) j++;
        const num = parseInt(s.slice(i, j), 10);
        i = j;
        const ni = new NestedInteger();
        ni.setInteger(num);
        return ni;
    }
    return parse();
};

