    def deserialize(self, s: str) -> NestedInteger:
        stack = []
        i, n = 0, len(s)
        cur = None
        while i < n:
            c = s[i]
            if c == '[':
                ni = NestedInteger()
                if stack:
                    stack[-1].add(ni)
                stack.append(ni)
                i += 1
            elif c == ']':
                cur = stack.pop()
                i += 1
            elif c == ',':
                i += 1
            else:
                j = i
                while j < n and (s[j].isdigit() or s[j] == '-'):
                    j += 1
                ni = NestedInteger(int(s[i:j]))
                if stack:
                    stack[-1].add(ni)
                else:
                    cur = ni
                i = j
        return cur

