class Solution {
    public NestedInteger deserialize(String s) {
        Deque<NestedInteger> st = new ArrayDeque<>();
        NestedInteger ans = null;
        int i = 0, n = s.length();
        while (i < n) {
            char c = s.charAt(i);
            if (c == '[') {
                NestedInteger ni = new NestedInteger();
                if (!st.isEmpty()) st.peek().add(ni);
                st.push(ni);
                i++;
            } else if (c == ']') {
                ans = st.pop();
                i++;
            } else if (c == ',') {
                i++;
            } else {
                int sign = 1;
                if (c == '-') { sign = -1; i++; }
                int val = 0;
                while (i < n && Character.isDigit(s.charAt(i))) val = val * 10 + (s.charAt(i++) - '0');
                NestedInteger ni = new NestedInteger(sign * val);
                if (!st.isEmpty()) st.peek().add(ni);
                else ans = ni;
            }
        }
        return ans;
    }
}

